SELECT *
FROM app_conversation_memory_entry
WHERE conversation_id = #{conversationId}
  AND branch_id = #{branchId}
ORDER BY id ASC
FOR UPDATE

SELECT *
FROM app_conversation_memory_entry
WHERE conversation_id = #{conversationId}
  AND branch_id = #{branchId}
ORDER BY id ASC
FOR UPDATE

SELECT *
FROM app_conversation_memory_entry
WHERE id = #{id}
  AND conversation_id = #{conversationId}
  AND branch_id = #{branchId}
  AND manual_deleted = FALSE
  AND (
      (deleted_at IS NULL AND retired_reason IS NULL AND retired_at IS NULL)
      OR (
          deleted_at IS NOT NULL
          AND retired_at IS NOT NULL
          AND retired_reason IN ('CAPACITY', 'DUPLICATE', 'SUPERSEDED')
      )
  )
LIMIT 1

mapper.update:
UPDATE app_conversation_memory_entry
SET enabled = 0,
    updated_at = CURRENT_TIMESTAMP
WHERE conversation_id = #{conversationId}
  AND branch_id = #{branchId}
  AND entry_key = #{entryKey}
  AND manual_pinned = FALSE
  AND deleted_at IS NULL

UPDATE app_conversation_memory_entry
SET constant_injection = #{constantInjection},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND conversation_id = #{conversationId}
  AND branch_id = #{branchId}
  AND enabled = TRUE
  AND deleted_at IS NULL
